@dataclass(frozen=True)
class StoreAck:
    ticket: Ticket
    previous: Ticket | None
    accepted: bool
    receipt_ref: str


@dataclass(frozen=True)
class DeliveryAck:
    ticket: Ticket
    receiver_ref: str
    accepted: bool
    receipt_ref: str


@dataclass(frozen=True)
class AdapterEvent:
    step: str
    attempted_ticket: Ticket
    observed_result: str


@dataclass(frozen=True)
class OwnerView:
    snapshot: Snapshot
    last_verified_stored_ticket: Ticket | None
    last_verified_delivered_ticket: Ticket | None
    events: tuple[AdapterEvent, ...]
    started: bool
    busy: bool


@dataclass(frozen=True)
